        StoryParagraph(205, ParagraphType.DIALOGUE, "Golden Knight", "Mana bisa aku tahan melihat orang sedih atau murung setelah bertempur mati-matian? Hidup itu harus cerah, kawan! Seperti cahayaku ini!"),
        StoryParagraph(206, ParagraphType.NARRATIVE, null, "Minggu-minggu pertama di ruang pemulihan pusat DHC menjadi masa yang menyiksa bagi Fatan. Di bawah bimbingan ketat Kael dan pengawasan Rose, Fatan belajar cara menstabilkan detak jantung dan menjernihkan pikirannya agar gelombang energinya tidak lagi memancarkan radiasi merusak. X-Power Positif yang berakar dari harapan dan keinginan untuk melindungi orang lain harus menjadi dinding utamanya!"),
        StoryParagraph(207, ParagraphType.NARRATIVE, null, "5 TAHUN KEMUDIAN... (Fatan kini berusia 19 tahun)."),
        StoryParagraph(208, ParagraphType.NARRATIVE, null, "Suara logam berat yang dihasilkan oleh Kael saat menarik tuas besi, membuka pintu baja tebal di ujung lorong fasilitas bawah tanah DHC. Di tengah ruangan, berdiri sebuah dummy baja setinggi tiga meter."),
        StoryParagraph(209, ParagraphType.DIALOGUE, "Kael", "*melalui mic speaker* Inilah kejutan yang dijanjikan oleh Rose. Dengar baik-baik, Fatan, sistem ruangan ini terhubung langsung dengan sensor gelombang otak dan detak jantungmu. Jika kau membiarkan emosimu lepas kendali dan menggunakan sedikit saja X-power negatif, sistem akan otomatis menggagalkanmu!"),
        StoryParagraph(210, ParagraphType.DIALOGUE, "Fatan", "*menarik napas panjang* Huff, jangan meremehkanku bung!"),
        StoryParagraph(211, ParagraphType.NARRATIVE, null, "Dummy melesat maju mengayunkan lengan bajanya! Pikiran pertama Fatan adalah amarah masa lalu, hidungnya mulai terasa panas, namun tawa Golden Knight dan senyum Rose tiba-tiba melintas di benaknya."),
        StoryParagraph(212, ParagraphType.DIALOGUE, "Fatan", "*menutup mata* Tidak... jangan pakai dendam. Tenang, Fatan, lindungi... jangan hancurkan!"),
        StoryParagraph(213, ParagraphType.DIALOGUE, "Fatan", "*membuka mata dengan kilatan cahaya putih* Scan data... Bentuklah!"),
        StoryParagraph(214, ParagraphType.NARRATIVE, null, "Sebagai Constructor, Fatan memadatkan energi menjadi pedang energi putih murni. Dalam satu lintasan cahaya tanpa amarah, ia menebas inti dummy baja hingga terbelah dua. Gelombang otaknya stabil!"),
        StoryParagraph(215, ParagraphType.NARRATIVE, null, "Di ruang lab divisi persenjataan DHC, Fatan merakit armor barunya yang diberi nama: White Spark!", "SCENE_WHITE_SPARK_BLUEPRINT"),
        StoryParagraph(216, ParagraphType.DIALOGUE, "Fatan", "Begitu gelombang otakku mulai tidak stabil atau reaktor hampir mencapai batas, sistem ini otomatis meretas aliran energinya, menyerap kelebihan panas, dan membuangnya sebagai pendorong jet tambahan, bukan cuma mencegah Brain-Overheat, ini akan membuat manuver udaraku jauh lebih lincah. Aku menyebutnya White Spark!"),
        StoryParagraph(217, ParagraphType.WARNING, null, "Tiba-tiba, lampu lab berubah menjadi merah berkedip! Celah dimensi terbuka di Sektor 7, iblis kelas A terdeteksi!"),
        StoryParagraph(218, ParagraphType.NARRATIVE, null, "Fatan memasang helm White Spark dan melesat dengan kecepatan roket luar biasa, menempuh jarak menuju Sektor 7 hanya dalam 3 detik! Pendaratannya meratakan seluruh iblis kelas A yang keluar dari celah dimensi!"),
        StoryParagraph(219, ParagraphType.NARRATIVE, null, "Namun tiba-tiba saluran komunikasi mati, dan sistem HUD mendeteksi sebuah Anomali di atas gedung."),
        StoryParagraph(220, ParagraphType.NARRATIVE, null, "Fatan berkedip satu kali. Saat matanya terbuka kurang dari satu detik kemudian, seluruh kota membisu. Warga lenyap, gedung-gedung runtuh menjadi debu tua. Waktu telah dimajukan berabad-abad!"),
        StoryParagraph(221, ParagraphType.DIALOGUE, "Time Conqueror", "Terlalu lambat. Berkedip di hadapanku sama saja dengan membiarkan berabad-abad berlalu begitu saja."),
        StoryParagraph(222, ParagraphType.DIALOGUE, "Fatan", "*mengayunkan pedang energi ke leher entitas itu* Mundur kau!"),
        StoryParagraph(223, ParagraphType.DIALOGUE, "Time Conqueror", "*bilah pedang Fatan berhenti membeku 1 milimeter dari lehernya* Reaksi yang bagus, tapi di areaku, masa depan seranganmu sudah kuhentikan sebelum kau memikirkannya. Mesinmu tidak rusak anak muda, hanya saja waktu di sekitarmu sudah tidak lagi berjalan."),
        StoryParagraph(224, ParagraphType.NARRATIVE, null, "Ujung jari Time Conqueror menyentuh dada White Spark. Area logam itu langsung berubah warna cokelat berkarat, mengelupas dan hancur menjadi serbuk dalam hitungan detik karena percepatan waktu ratusan tahun!", "SCENE_TIME_CONQUEROR"),
        StoryParagraph(225, ParagraphType.DIALOGUE, "Fatan", "*memaksa rahangnya bergerak* Kalau begitu... aku buang saja bagian yang rusak!"),
        StoryParagraph(226, ParagraphType.NARRATIVE, null, "Fatan meretas paksa komputernya sendiri, melepaskan pelat dada yang membusuk, dan menyalakan pendorong darurat di punggungnya hingga terlempar mundur menjauh!"),
        StoryParagraph(227, ParagraphType.DIALOGUE, "Time Conqueror", "Kau merusak senjatamu sendiri hanya untuk menjauh dariku? Tindakan ceroboh."),
        StoryParagraph(228, ParagraphType.DIALOGUE, "Fatan", "*tersenyum dengan darah mengalir dari hidungnya* Bukan putus asa! Jika kau bisa membusukkan benda fisik dengan waktu, aku akan menghajarmu menggunakan ini!"),
        StoryParagraph(229, ParagraphType.NARRATIVE, null, "Ratusan baris kode digital dan proyeksi hologram biru keluar dari tangan Fatan, membentuk ribuan peluru energi yang meretas data secara real-time sebelum dapat dituakan oleh waktu!"),
        StoryParagraph(230, ParagraphType.DIALOGUE, "Time Conqueror", "*terdorong mundur dua langkah oleh ledakan energi* Begitu rupanya. Kau meretas paksa kodenya untuk terus memperbarui kondisinya ke masa kini!"),
        StoryParagraph(231, ParagraphType.DIALOGUE, "Fatan", "*tertawa di tengah Brain-Overheat* Armorku mungkin bisa kau busukkan, tapi rancangan di dalam kepalaku tidak bisa menua! Bang Kael... kalau aku koma setelah ini, maafkan aku yah!"),
        StoryParagraph(232, ParagraphType.ACTION_EFFECT, null, "*HANTAMAN TOMBAK DATA RAKSASA MENELAN SEKTOR 7!!*")
    )

    val arc3Paragraphs = listOf(
        StoryParagraph(301, ParagraphType.NARRATIVE, null, "Hantaman tombak data raksasa menciptakan kawah besar. Fatan jatuh dan berlutut, darah mengalir dari hidung, mata, dan telinganya akibat Brain-Overheat melampaui batas fatal."),
        StoryParagraph(302, ParagraphType.DIALOGUE, "Time Conqueror", "*berdiri tanpa noda di tengah kawah* Usaha yang brilian untuk seorang manusia, tapi kau melupakan satu hal: aku hanya perlu memutar mundur waktu pada tubuhku sendiri ke satu detik sebelum serangan itu mengenaimu. Kau membakar nyawamu untuk menyakiti sesuatu yang sudah tidak berada di masa itu."),
        StoryParagraph(303, ParagraphType.NARRATIVE, null, "Cahaya reaktor Fatan padam, kapasitas X-Power anjlok ke bawah 1%, dan tubuhnya ambruk pingsan. Time Conqueror membalikkan badan dan menghilang ke celah distorsi udara."),
        StoryParagraph(304, ParagraphType.NARRATIVE, null, "Fatan koma selama 7 hari di markas DHC. Saat sadar, Kael menjatuhkan sanksi mutlak: dilarang operasi dan dilarang masuk laboratorium selama 3 bulan penuh karena sistem sarafnya hancur!"),
        StoryParagraph(305, ParagraphType.NARRATIVE, null, "Satu bulan kemudian, Rose memperkenalkan anggota tim barunya: Zephyr (Pengendali Badai), Lio (Spesialis Es), Rina (Ahli Tebasan Energi), Finn (Analis Taktis), dan The Void (Penyerap Ruang Hampa)."),
        StoryParagraph(306, ParagraphType.DIALOGUE, "The Void", "*mengulurkan tangan hangat* Namaku The Void. Aku menyerap energi dari ruang hampa, kuharap kekuatanku bisa menjadi perisai untuk melindungimu dan yang lainnya, Fatan."),
        StoryParagraph(307, ParagraphType.NARRATIVE, null, "Tiga bulan kemudian di bunker bawah tanah rahasia, Fatan mencoba menyelinap untuk merakit armor baru dan digerebek langsung oleh Rose!"),
        StoryParagraph(308, ParagraphType.DIALOGUE, "Rose", "*tersenyum manis tapi auranya mematikan* Ignis Burst! Buktikan padaku kalau kau tidak akan jadi beban tanpa merebus otakmu sendiri!"),
        StoryParagraph(309, ParagraphType.NARRATIVE, null, "Bola api seukuran mobil melesat dengan kecepatan supersonik 400 m/s! Fatan bermanuver zig-zag melintasi 50 meter dalam 0,2 detik dengan pendorong kinetiknya tanpa memicu amarah negatif!"),
        StoryParagraph(310, ParagraphType.NARRATIVE, null, "Hari latihan gabungan bersama para Petinggi DHC dimulai: Whiteshine (Densitas Otot Puluhan Ton), Aspire (Manipulasi Realitas), Golden Knight (Kecepatan Cahaya), dan Mat Cover (Gempa Energi)!"),
        StoryParagraph(311, ParagraphType.NARRATIVE, null, "Formasi gabungan tim beraksi! Mat Cover melompat menghantamkan bola energi raksasa, namun sebagian besar ledakannya ditelan ke dalam distorsi hitam oleh The Void!", "SCENE_DHC_TEAM_COMBO"),
        StoryParagraph(312, ParagraphType.NARRATIVE, null, "Golden Knight menembakkan ratusan peluru cahaya, dibelokkan oleh badai topan Zephyr dan ditahan oleh kubah es Lio! Finn menahan pukulan telak puluhan ton milik Whiteshine!"),
        StoryParagraph(313, ParagraphType.NARRATIVE, null, "Aspire mengubah gravitasi lapangan menjadi balok-balok beton melayang. Fatan memerintahkan: 'Void, serap panasnya, biarkan energi kinetiknya masuk ke armorku!' Daya reaktor White Spark melesat dari 15% langsung ke 85%!"),
        StoryParagraph(314, ParagraphType.NARRATIVE, null, "Rina melompat menebas Energy Slash, Lio membekukannya menjadi bilah es raksasa, dan Zephyr melontarkannya ke arah Aspire! Fatan melesat zig-zag secepat kilat menembus formasi hingga berdiri di depan Rose dan Aspire!"),
        StoryParagraph(315, ParagraphType.DIALOGUE, "Fatan", "*tersenyum* Realitas dan sihir memang hebat, tapi delay waktu untuk mengaktifkannya adalah titik buta kalian!"),
        StoryParagraph(316, ParagraphType.DIALOGUE, "Rose", "*tersenyum licik* Trik yang berani, tapi apa kau pikir seorang penyihir akan membiarkan garis belakangnya tanpa perlindungan kedua? *Cincin sihir ungu mengunci kaki Fatan dengan rantai duri!*"),
        StoryParagraph(317, ParagraphType.NARRATIVE, null, "Latihan berakhir dengan gelak tawa dan pujian dari para petinggi DHC. Tim baru Fatan berhasil membuktikan sinergi luar biasa mereka, siap menyongsong ancaman iblis bawah tanah yang sedang direncanakan oleh Vinki!")
    )

    val arc4PreviewParagraphs = listOf(
        StoryParagraph(401, ParagraphType.WARNING, null, "[TEASER BAB MENDATANG: ARC 4 - EMBRIO BAWAH TANAH]"),
        StoryParagraph(402, ParagraphType.NARRATIVE, null, "Jauh di bawah kerak bumi Sektor 4, sisa radiasi Malignant Energy dari pertarungan pertama Fatan mulai menetas. Tiga embrio iblis raksasa menyatu dengan energi gravitasi mata merah milik Vinki."),
        StoryParagraph(403, ParagraphType.DIALOGUE, "Vinki", "Waktunya telah tiba... Fatan dan DHC akan menyadari bahwa armor terkuat sekalipun tidak bisa menahan gravitasi lubang hitam buatan manusia."),
        StoryParagraph(404, ParagraphType.NARRATIVE, null, "Aktifkan notifikasi aplikasi untuk mendapatkan pemberitahuan seketika saat Bab Arc 4 resmi dirilis!")
    )

